def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    # Immediate retaliation, but check for opponent's long-run cooperativeness
    if last_opp == 'D':
        # If opponent has defected only once and otherwise cooperated, retaliate once
        opp_d = sum(1 for o in opp if o == 'D')
        if n >= 5 and opp_d == 1:
            return 'D'
        # If opponent is generally cooperative and just defected, retaliate once
        if n >= 10:
            recent = opp[-6:]
            r_d = recent.count('D')
            if r_d == 1 and opp_d * 3 <= n:
                return 'D'
        return 'D'

    # Opponent cooperated. Look for opportunism near the end.
    rounds_left = 100 - n
    if rounds_left == 1:
        return 'D'
    if rounds_left <= 3:
        # Defect only if opponent has been sufficiently cooperative to likely not retaliate harshly
        opp_d = sum(1 for o in opp if o == 'D')
        if opp_d <= max(1, n // 12):
            return 'D'
    if rounds_left <= 5 and n >= 30:
        recent = opp[-10:]
        if recent.count('C') >= 9:
            return 'D'

    # Retaliate against sustained defection
    if n >= 6:
        recent = opp[-6:]
        if recent.count('D') >= 3:
            return 'D'

    # If opponent has never defected, keep cooperating until final round
    if opp.count('D') == 0:
        return 'C'

    # If our recent defections outpace opponent's, return to cooperation to avoid DD cycles
    if n >= 8:
        my_recent_d = me[-6:].count('D')
        if my_recent_d >= 3 and last_me == 'D':
            return 'C'

    # Tit-for-tat-like default: cooperate since opponent cooperated
    return 'C'
